/bin/bash -lc "python - <<'PY'
import numpy as np
from sim import Sim

def trial(torso,hip,knee,ank,steps=800):
    sim=Sim(); c=sim.home_ctrl();
    c[2]+=hip; c[7]+=hip; c[3]+=knee; c[8]+=knee; c[4]+=ank; c[9]+=ank; c[10]=torso
    for _ in range(steps):
        sim.data.ctrl[:]=c; sim.step(1)
    p=sim.pelvis_position(); up=sim.torso_up()
    # settle
    minz=1e9; minu=1e9
    for _ in range(500):
        sim.step(1)
        minz=min(minz,sim.pelvis_position()[2]); minu=min(minu,sim.torso_up())
    return p[0],p[2],up,minz,minu,sim.distance_to_target()

for torso in [-0.4,-0.2,0.0,0.2,0.4]:
  for hip in [-0.2,-0.1,0.0,0.1,0.2]:
    x,z,up,mz,mu,d=trial(torso,hip,0.0,0.0)
    if mz>0.23 and mu>0.55:
      print('stable', 'torso',torso,'hip',hip,'x',round(x,3),'dist',round(d,3),'z',round(z,3),'up',round(up,3))
PY"

