/bin/bash -lc "python - <<'PY'
from sim import Sim

def trial(torso,hip,knee=0,ank=0,steps=600):
    sim=Sim(); c=sim.home_ctrl();
    c[2]+=hip; c[7]+=hip; c[3]+=knee; c[8]+=knee; c[4]+=ank; c[9]+=ank; c[10]=torso
    for _ in range(steps):
        sim.data.ctrl[:]=c; sim.step(1)
    x=sim.pelvis_position()[0]
    # settle
    minz=9;minu=9
    for _ in range(300):
      sim.step(1)
      minz=min(minz,sim.pelvis_position()[2]);minu=min(minu,sim.torso_up())
    return x,sim.distance_to_target(),minz,minu

vals=[]
for torso in [-0.5,-0.3,-0.1,0.1,0.3,0.5]:
  for hip in [-0.3,-0.2,-0.1,0,0.1,0.2,0.3]:
    x,d,mz,mu=trial(torso,hip)
    vals.append((x,d,mz,mu,torso,hip))
vals=sorted(vals,key=lambda t:t[1])
for v in vals[:20]:
  print('x %.3f d %.3f mz %.3f mu %.3f torso %.2f hip %.2f'%v)
PY"

